import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, normalLocal, positionLocal, texture, uniform, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color,
    PointLight,
    AmbientLight,
    DoubleSide,
    SRGBColorSpace
  } = THREE;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
    ...(config.intent?.visualSpec?.colors || {})
  };

  const root = new Group();
  root.name = config.id || 'features-stat-tile';

  const resources = [];
  const timelines = [];
  const primitiveCleanups = [];
  let disposed = false;

  const remember = (resource) => {
    if (resource) resources.push(resource);
    return resource;
  };

  const makeBasic = (color, options = {}) => {
    const material = new MeshBasicNodeMaterial({
      color: new Color(color),
      ...options
    });
    remember(material);
    return material;
  };

  const makeStandard = (color, options = {}) => {
    const material = new MeshStandardNodeMaterial({
      color: new Color(color),
      roughness: 0.62,
      metalness: 0.42,
      ...options
    });
    remember(material);
    return material;
  };

  const backdropMaterial = makeBasic(colors.surface);
  const backdropInk = uniform(new Color(colors.ink));
  const backdropSurface = uniform(new Color(colors.surface));
  backdropMaterial.colorNode = mix(backdropSurface, backdropInk, uv().y);

  const backdrop = new Mesh(
    remember(new PlaneGeometry(7, 6, 1, 1)),
    backdropMaterial
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const shadowMaterial = makeBasic(colors.surface, {
    transparent: true,
    opacity: 0.48,
    side: DoubleSide,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    remember(new CircleGeometry(1.65, 48)),
    shadowMaterial
  );
  contactShadow.name = 'contact-shadow';
  contactShadow.scale.set(1.45, 0.42, 1);
  contactShadow.position.set(0, -1.02, -0.08);
  root.add(contactShadow);

  const cardWidth = 3.15;
  const cardHeight = 1.82;
  const cardDepth = 0.12;

  const cardGeometry = remember(
    new PlaneGeometry(cardWidth, cardHeight, 64, 64)
  );

  const cardMaterial = makeStandard(colors.paper, {
    side: DoubleSide,
    roughness: 0.58,
    metalness: 0.34
  });

  const displacementAmount = uniform(0.105);
  cardMaterial.positionNode = positionLocal.add(
    normalLocal.mul(
      texture(
        new THREE.Texture()
      ).r.sub(0.5).mul(displacementAmount)
    )
  );

  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'parallax-stat-surface';
  card.position.z = 0.04;
  root.add(card);

  const frameMaterial = makeStandard(colors.ink, {
    roughness: 0.56,
    metalness: 0.5
  });

  const frameTop = new Mesh(
    remember(new BoxGeometry(cardWidth + 0.12, 0.075, cardDepth)),
    frameMaterial
  );
  const frameBottom = new Mesh(
    remember(new BoxGeometry(cardWidth + 0.12, 0.075, cardDepth)),
    frameMaterial
  );
  const frameLeft = new Mesh(
    remember(new BoxGeometry(0.075, cardHeight, cardDepth)),
    frameMaterial
  );
  const frameRight = new Mesh(
    remember(new BoxGeometry(0.075, cardHeight, cardDepth)),
    frameMaterial
  );

  frameTop.position.set(0, cardHeight * 0.5 + 0.025, 0.12);
  frameBottom.position.set(0, -cardHeight * 0.5 - 0.025, 0.12);
  frameLeft.position.set(-cardWidth * 0.5 - 0.025, 0, 0.12);
  frameRight.position.set(cardWidth * 0.5 + 0.025, 0, 0.12);

  root.add(frameTop, frameBottom, frameLeft, frameRight);

  const focusMaterial = makeBasic(colors.accent, {
    transparent: true,
    opacity: 0.18,
    depthWrite: false
  });

  const focusEdge = new Mesh(
    remember(new BoxGeometry(cardWidth + 0.22, 0.025, 0.035)),
    focusMaterial
  );
  focusEdge.name = 'accent-focus-edge';
  focusEdge.position.set(0, cardHeight * 0.5 + 0.075, 0.18);
  root.add(focusEdge);

  const rim = new PointLight(new Color(colors.accent), 0.72, 5.5, 2);
  rim.position.set(-2.1, 1.7, 2.2);
  root.add(rim);

  const fill = new AmbientLight(new Color(colors.paper), 0.18);
  root.add(fill);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose?.();
        return;
      }
      tex.colorSpace = SRGBColorSpace;
      remember(tex);
      cardMaterial.colorNode = texture(tex);
      cardMaterial.needsUpdate = true;
    });
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTex) => {
      if (disposed) {
        depthTex.dispose?.();
        return;
      }
      remember(depthTex);
      cardMaterial.positionNode = positionLocal.add(
        normalLocal.mul(
          texture(depthTex).r.sub(0.5).mul(displacementAmount)
        )
      );
      cardMaterial.needsUpdate = true;
    });
  }

  const primitiveList = config.cinematicPrimitives || [];
  for (const primitive of primitiveList) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params || {});
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
      if (result?.timeline) timelines.push(result.timeline);
    }
  }

  const baseY = root.position.y;
  const entrance = gsap.fromTo(
    root,
    { y: baseY + 0.4, scaleX: 0.985, scaleY: 0.985, scaleZ: 0.985 },
    {
      y: baseY,
      scaleX: 1,
      scaleY: 1,
      scaleZ: 1,
      duration: 0.7,
      ease: 'power3.out'
    }
  );
  timelines.push(entrance);

  const handlers = {
    hover(active = true) {
      const isActive =
        typeof active === 'object' ? active.active !== false : active !== false;

      const hoverTimeline = gsap.to(root, {
        y: isActive ? baseY + 0.15 : baseY,
        rotation.x: isActive ? -0.035 : 0,
        rotation.y: isActive ? 0.045 : 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true
      });
      timelines.push(hoverTimeline);
    },

    click() {
      const pressTimeline = gsap.timeline();
      pressTimeline
        .to(root, {
          scaleX: 0.97,
          scaleY: 0.97,
          scaleZ: 0.97,
          duration: 0.12,
          ease: 'power2.out'
        })
        .to(root, {
          scaleX: 1.04,
          scaleY: 1.04,
          scaleZ: 1.04,
          duration: 0.22,
          ease: 'power3.out'
        })
        .to(root, {
          scaleX: 1,
          scaleY: 1,
          scaleZ: 1,
          duration: 0.5,
          ease: 'power4.out'
        });
      timelines.push(pressTimeline);
      ctx.emit('hub-features.select', {
        nodeId: config.id || 'features-stat-tile'
      });
    },

    focus(active = true) {
      const isActive =
        typeof active === 'object' ? active.active !== false : active !== false;

      const focusTimeline = gsap.to(focusMaterial, {
        opacity: isActive ? 0.92 : 0.18,
        duration: 0.18,
        ease: 'power2.out',
        overwrite: true
      });
      timelines.push(focusTimeline);
    }
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup?.();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material && !resources.includes(object.material)) {
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => material.dispose?.());
        } else {
          object.material.dispose?.();
        }
      }
    });

    for (const resource of resources) {
      resource.dispose?.();
    }

    root.clear();
  };

  return root;
}
